function officialUrl(appUrl, path) {
  const base = appUrl.replace(/\/+$/, "");
  const clean = path.startsWith("/") ? path : `/${path}`;
  return `${base}${clean}`;
}
function selectRelevantArticles(message, articles = KNOWLEDGE_ARTICLES, limit = 3) {
  const text = ` ${message.toLowerCase()} `;
  const scored = articles.map((article) => {
    let score = 0;
    for (const keyword of article.keywords) {
      const needle = keyword.toLowerCase();
      if (!needle) continue;
      if (new RegExp(`(^|[^a-z0-9])${escapeRegExp(needle)}([^a-z0-9]|$)`).test(text)) {
        score += needle.includes(" ") ? 2 : 1;
      }
    }
    return { article, score };
  }).filter((entry) => entry.score > 0).sort((a, b) => b.score - a.score);
  return scored.slice(0, limit).map((entry) => entry.article);
}
function escapeRegExp(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}
function sourcesFor(articles, appUrl) {
  const seen = /* @__PURE__ */ new Set();
  const out = [];
  for (const article of articles) {
    const path = article.links[0];
    if (!path) continue;
    const url = officialUrl(appUrl, path);
    if (seen.has(url)) continue;
    seen.add(url);
    out.push({ title: article.title, url });
  }
  return out;
}

